def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}

    def normalize_status(status: str | None) -> str | None:
        if not status:
            return None
        s = str(status).strip().lower()
        if s in ("passed", "pass", "ok", "success"):
            return "pass"
        if s in ("failed", "fail", "error", "timedout", "timeout", "failure"):
            return "fail"
        if s in ("skipped", "skip", "pending", "todo", "disabled", "ignored", "cancelled"):
            return "skip"
        return None

    def add_result(name: str | None, status: str, suite_name: str | None = None) -> None:
        if not name:
            return
        key = name
        if key in results:
            if suite_name:
                key = f"{suite_name}::{name}"
            if key in results:
                base = key
                idx = 2
                while key in results:
                    key = f"{base} #{idx}"
                    idx += 1
        results[key] = status

    def parse_assertions(container: dict) -> None:
        suites = []
        if isinstance(container.get("testResults"), list):
            suites = container["testResults"]
        else:
            suites = [container]

        for suite in suites:
            if not isinstance(suite, dict):
                continue
            suite_name = (
                suite.get("name")
                or suite.get("file")
                or suite.get("filepath")
                or suite.get("testFilePath")
            )
            assertions = (
                suite.get("assertionResults")
                or suite.get("assertions")
                or suite.get("tests")
                or []
            )
            if isinstance(assertions, dict):
                assertions = list(assertions.values())
            for case in assertions:
                if not isinstance(case, dict):
                    continue
                status = normalize_status(case.get("status"))
                if status is None:
                    status = normalize_status(case.get("outcome") or case.get("result"))
                if status is None:
                    continue
                name = case.get("fullName") or case.get("name") or case.get("title")
                if not name:
                    ancestors = case.get("ancestorTitles") or case.get("ancestors") or []
                    title = case.get("title") or case.get("name")
                    parts = [str(a) for a in ancestors if a]
                    if title:
                        parts.append(str(title))
                    if parts:
                        name = " ".join(parts)
                add_result(name, status, suite_name)

    # Attempt to parse JSON objects from the log (robust to noise)
    decoder = json.JSONDecoder()
    idx = 0
    while idx < len(log):
        start = log.find("{", idx)
        if start == -1:
            break
        try:
            obj, offset = decoder.raw_decode(log[start:])
        except Exception:
            idx = start + 1
            continue
        idx = start + offset
        if isinstance(obj, dict):
            if "testResults" in obj or "assertionResults" in obj:
                parse_assertions(obj)

    if results:
        return results

    # Fallback regex parsing for non-JSON outputs
    for line in log.splitlines():
        line = line.strip()
        if not line:
            continue

        # pytest
        m = re.search(r"(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR|XFAIL|XPASS)", line)
        if m:
            status = normalize_status(m.group(2))
            if status:
                add_result(m.group(1), status)
            continue

        # go test
        m = re.search(r"---\s+(PASS|FAIL|SKIP):\s+(\S+)", line)
        if m:
            status = normalize_status(m.group(1))
            if status:
                add_result(m.group(2), status)
            continue

        # jest symbols
        m = re.search(r"^(✓|✔|✕|×|✗|○|◌)\s+(.+)$", line)
        if m:
            symbol = m.group(1)
            status = {
                "✓": "pass",
                "✔": "pass",
                "✕": "fail",
                "×": "fail",
                "✗": "fail",
                "○": "skip",
                "◌": "skip",
            }.get(symbol)
            if status:
                add_result(m.group(2).strip(), status)
            continue

        # TAP
        m = re.search(r"^(ok|not ok)\s+\d+\s+-\s+(.+)$", line, re.IGNORECASE)
        if m:
            status = "pass" if m.group(1).lower() == "ok" else "fail"
            add_result(m.group(2).strip(), status)
            continue

        # unittest style: name ... ok/FAIL/ERROR/SKIP
        m = re.search(r"^(.*?)\s+\.\.\.\s+(ok|FAIL|ERROR|SKIP|SKIPPED)$", line, re.IGNORECASE)
        if m:
            status = normalize_status(m.group(2))
            if status:
                add_result(m.group(1).strip(), status)
            continue

    return results
